-- FormatPrice(35000, 1) -> "35,000 Gold". Same wording the addon
-- puts on its tooltips, minus the icon.
local function FormatPrice(amount, currency)
  local formatted = tostring(amount or 0)
  while true do
    local replaced
    formatted, replaced = formatted:gsub("^(%-?%d+)(%d%d%d)", "%1,%2")
    if replaced == 0 then
      break
    end
  end
  local info = CURRENCIES[currency]
  return (info and formatted .. " " .. info.name) or formatted
end

-- Source texts carry a currency as `{c<id>}`; ResolveText spells it out.
local function ResolveText(text)
  return (tostring(text or ""):gsub("{c(%d+)}", function(id)
    local info = CURRENCIES[tonumber(id)]
    return (info and info.name) or ""
  end))
end

